function localizeDemo(value, language) {
  if (language !== "zh" || typeof value !== "string") return value;
  if (demoMessages[value]) return demoMessages[value];
  return value
    .replace(/^(.+) was (.+) across (\d+) recorded plans?\. In the next plan, try a (\d+)-minute version(?: at (\d{2}:\d{2}))? and make the first step: (.+)\.$/,
      (_, task, outcome, plans, minutes, time, step) => `${demoMessages[task] || task}在 ${plans} 份已记录计划中${outcome.replace(/skipped once/, "跳过 1 次").replace(/skipped (\d+) times/, "跳过 $1 次").replace(/partly completed once/, "部分完成 1 次").replace(/partly completed (\d+) times/, "部分完成 $1 次").replace(" and ", "，且")}。下一份计划${time ? `在 ${time} ` : ""}安排 ${minutes} 分钟，第一步是：${demoMessages[step] || step}。`)
    .replace(/^On (\d{4}-\d{2}-\d{2}), energy was (\d)\/5\. Keep (.+?)(?: at (\d{2}:\d{2}))? for (\d+) minutes in the next plan\.$/,
      (_, date, level, task, time, minutes) => `${date} 的精力为 ${level}/5。下一份计划${time ? `在 ${time} ` : ""}保留${demoMessages[task] || task}的 ${minutes} 分钟。`)
    .replace(/^On (\d{4}-\d{2}-\d{2}), energy was (\d)\/5\. Keep the next plan lighter than a normal day\.$/,
      (_, date, level) => `${date} 的精力为 ${level}/5。下一份计划比平时轻松一些。`)
    .replace(/^Review the size or timing of learning work before the next plan\.$/, "在制定下一份计划前，重新评估学习任务的时长或时间安排。")
    .replace(/^Review the size or timing of life work before the next plan\.$/, "在制定下一份计划前，重新评估生活任务的时长或时间安排。")
    .replace(/^Adds 15 minutes to “?(.+?)”? where the saved calendar has room; fixed times and repeatedly disliked tasks stay unchanged\.$/,
      (_, item) => `在已保存日程有空间时，为“${demoMessages[item] || item}”增加 15 分钟；固定时间和反复不喜欢的任务保持不变。`)
    .replace(/^Shortens “?(.+?)”? by 15 minutes, never removes it; fixed commitments stay unchanged\.$/,
      (_, item) => `将“${demoMessages[item] || item}”缩短 15 分钟但不删除；固定安排保持不变。`)
    .replace(/^Keeps your fixed times and places tasks without a start time from (\d{2}:\d{2}), one area at a time in turn\. A task you usually do at a set time goes near it, and a flexible task you asked to shorten, or often leave unfinished, loses 15 minutes but is never removed\.$/,
      (_, time) => `保留固定时间，从 ${time} 起按领域轮流安排没有开始时间的任务。你通常在固定时间做的任务会安排在那个时间附近；你要求缩短或经常没做完的灵活任务会减少 15 分钟，但不会被删除。`)
    .replace(/^Places learning, then project, then work first while attention is fresh(?:, and gives “?(.+?)”? 15 more minutes)?; fixed times and repeatedly shortened tasks stay as they are\.$/,
      (_, item) => `趁精力充沛先安排学习、项目、工作${item ? `，并为“${demoMessages[item] || item}”增加 15 分钟` : ""}；固定时间和反复要求缩短的任务保持不变。`)
    .replace(/^(Listed first because the Life agent advised a lighter day\. )?Starts placing from (\d{2}:\d{2}), life tasks first, and leaves 15 minutes after each task it places(?:; shortens “?(.+?)”? by 15 minutes without removing it)?; fixed times stay as they are\.$/,
      (_, first, time, item) => `${first ? "排在第一位，因为生活智能体建议今天轻松一些。" : ""}从 ${time} 起开始安排，先安排生活任务，每安排一项任务后留出 15 分钟${item ? `；将“${demoMessages[item] || item}”缩短 15 分钟但不删除` : ""}；固定时间保持不变。`);
}

/**
 * Look up interface text in a language, falling back to English and then the key.
 * @param {"en"|"zh"} language - The interface language.
 * @param {string} key - The message key.
 * @param {object} [values] - Replacements for `{name}` placeholders in the message.
 * @returns {string} The message.
 */
export function translate(language, key, values) {
  const normalized = typeof key === "string" ? key.toLowerCase() : key;
  const text = messages[language][key] || messages[language][normalized] || messages.en[key] || messages.en[normalized] || key;
  return values ? text.replace(/\{(\w+)\}/g, (match, name) => (name in values ? String(values[name]) : match)) : text;
}

const LanguageContext = createContext(null);

export function LanguageProvider({ children }) {
  const [language, setLanguage] = useState(() => localStorage.getItem("daywright-language") || "en");
  useEffect(() => { document.documentElement.lang = language === "zh" ? "zh-Hans" : "en"; }, [language]);
  const value = useMemo(() => ({
    language,
    setLanguage(next) {
      localStorage.setItem("daywright-language", next);
      document.documentElement.lang = next === "zh" ? "zh-Hans" : "en";
      setLanguage(next);
    },
    /**
     * Look up interface text in the current language; see {@link translate}.
     * @param {string} key - The message key.
     * @param {object} [values] - Replacements for `{name}` placeholders in the message.
     * @returns {string} The message.
     */
    t(key, values) {
      return translate(language, key, values);
    },
    demoText(value) { return localizeDemo(value, language); },
  }), [language]);
  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}

export function useI18n() {
  return useContext(LanguageContext);
}
